-- Finished-game records (brief §4 T1): one row per finished game,
-- idempotent on (user_id, id) — the id is generated by the client so a
-- retried upload lands on the same row. The decision log is stored
-- verbatim as jsonb; the server never interprets it. Per-game stat
-- counters are flattened into columns so /api/stats is a plain SUM.
CREATE TABLE IF NOT EXISTS games (
  user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  id          uuid NOT NULL,
  length      text NOT NULL CHECK (length IN ('east', 'south')),
  placement   integer NOT NULL CHECK (placement BETWEEN 1 AND 4),
  score       double precision NOT NULL,
  finished_at timestamptz NOT NULL,
  log         jsonb NOT NULL,
  hands       integer NOT NULL,
  riichi      integer NOT NULL,
  deal_ins    integer NOT NULL,
  hands_won   integer NOT NULL,
  win_points  bigint NOT NULL,
  PRIMARY KEY (user_id, id)
);

CREATE INDEX IF NOT EXISTS games_user_finished_idx
  ON games (user_id, finished_at DESC);
